parent,oldcase,case,output=map(Path,sys.argv[1:]);sha=lambda p:hashlib.file_digest(Path(p).open('rb'),'sha256').hexdigest();proof=json.loads((parent/'assessment.json').read_text());r=json.loads((case/'agglomeration.json').read_text());native=json.loads((case/'native-check.json').read_text());assert not output.exists()
