z=np.load(parent/'volume.npz');m=np.load(case/'agglomeration.npz');p2n=m['parent_to_native'];p2new=m['parent_to_new'];pairs=m['pairs'];v0,f0,o0,n0,patch0=aggl.read_mesh(oldcase);v,f,o,n,patches=aggl.read_mesh(case);ni=len(n);nc=len(z['tetrahedra'])-len(pairs)
