assert np.array_equal(np.sort(p2n),np.arange(len(p2n)));old_tets,_=aggl.tetrahedra(f0,o0,n0,len(p2n));assert np.array_equal(old_tets[p2n],np.sort(z['tetrahedra'],axis=1))
