removed=np.setdiff1d(np.arange(len(f0)),ids);actual_pairs=np.sort(np.column_stack([o0[removed],n0[removed]]),axis=1);wanted=np.sort(p2n[pairs],axis=1);order=lambda a:np.lexsort(a.T[::-1]);assert len(removed)==len(pairs) and np.array_equal(actual_pairs[order(actual_pairs)],wanted[order(wanted)])
old_to_new=np.empty(len(p2n),dtype=np.int64);old_to_new[p2n]=p2new;eo=old_to_new[o0[ids]];en=old_to_new[n0[ids[:ni]]];mask=rev[:ni];eo[:ni][mask],en[mask]=en[mask].copy(),eo[:ni][mask].copy();assert np.array_equal(eo,o) and np.array_equal(en,n)
assert [(a,b,c) for a,b,c,_ in patch0]==[(a,b,c) for a,b,c,_ in patches] and np.array_equal(f[ni:],f0[len(n0):])
witnesses=aggl.partition(v,z['tetrahedra'],pairs);assert witnesses==r['exact_convex_cell_volume_witnesses']
for pair,witness in zip(pairs,witnesses):
 cell=int(p2new[pair[0]]);oriented=np.vstack([f[o==cell],f[:ni][n==cell][:,::-1]]);used=np.unique(oriented);points,_=aggl.integer_points(v[used]);lookup=dict(zip(used,points));values=[aggl.determinant(points[0],*(lookup[int(i)] for i in face)) for face in oriented];assert min(values)>=0 and sum(values)==int(witness)
xyz=z['vertices'][z['tetrahedra']];volume=np.einsum('ij,ij->i',xyz[:,1]-xyz[:,0],np.cross(xyz[:,2]-xyz[:,0],xyz[:,3]-xyz[:,0]))/6;assert np.all(volume>0);expected_v=np.bincount(p2new,weights=volume,minlength=nc);expected_c=np.column_stack([np.bincount(p2new,weights=volume*xyz.mean(axis=1)[:,j],minlength=nc)/expected_v for j in range(3)])
def field(name,columns,dimensions):
 text=(case/'0'/name).read_text();dim=re.search(r'\bdimensions\s*\[([^]]+)\]\s*;',text);assert dim and np.array_equal(np.fromstring(dim[1],sep=' '),dimensions)
 match=re.search(r'\binternalField\s+nonuniform\s+List<(?:vector|scalar)>\s+(\d+)\s*\((.*?)\)\s*;',text,re.S)
 if match:
  a=np.fromstring(match[2].replace('(',' ').replace(')',' '),sep=' ');assert int(match[1])==nc and a.size==nc*columns;return a.reshape(nc,columns)
 match=re.search(r'\binternalField\s+uniform\s+([^;]+);',text);assert match;a=np.fromstring(match[1].replace('(',' ').replace(')',' '),sep=' ');assert a.size==columns;return np.broadcast_to(a,(nc,columns)).copy()
centres=field('C',3,[0,1,0,0,0,0,0]);volumes=field('Vc',1,[0,3,0,0,0,0,0]).ravel();assert np.allclose(centres,expected_c,rtol=0,atol=1e-12) and np.allclose(volumes,expected_v,rtol=1e-9,atol=1e-21)
(case/'verify-mixed-002.foam').touch(exist_ok=False);reader=vtk.vtkOpenFOAMReader();reader.SetFileName(str(case/'verify-mixed-002.foam'));reader.SetUse64BitFloats(True);reader.SetCreateCellToPoint(False);reader.UpdateInformation();reader.DisableAllCellArrays();reader.DisableAllPatchArrays();reader.SetPatchArrayStatus('internalMesh',1);reader.Update();grid=reader.GetOutput().GetBlock(0);assert grid.GetNumberOfCells()==nc and grid.GetNumberOfPoints()==len(v) 
vtk_points=vtk_to_numpy(grid.GetPoints().GetData());assert np.array_equal(vtk_points,v.astype(vtk_points.dtype));rounded_vertices=vtk_points.astype(np.float64)
types=vtk_to_numpy(grid.GetCellTypesArray());single=np.flatnonzero(hist[p2new]==1);assert np.all(types[p2new[single]]==vtk.VTK_TETRA);offsets=vtk_to_numpy(grid.GetCells().GetOffsetsArray());connectivity=vtk_to_numpy(grid.GetCells().GetConnectivityArray());actual=connectivity[offsets[p2new[single]][:,None]+np.arange(4)];assert np.array_equal(np.sort(actual,axis=1),np.sort(z['tetrahedra'][single],axis=1))
for pair in pairs:
 index=int(p2new[pair[0]]);assert types[index]==vtk.VTK_POLYHEDRON;cell=grid.GetCell(index);expected=np.unique(z['tetrahedra'][pair]);assert sorted(cell.GetPointId(j) for j in range(cell.GetNumberOfPoints()))==expected.tolist()
 faces=np.array([[cell.GetFace(j).GetPointId(k) for k in range(cell.GetFace(j).GetNumberOfPoints())] for j in range(cell.GetNumberOfFaces())]);assert np.array_equal(np.sort(faces,axis=1)[order(np.sort(faces,axis=1))],aggl.base.outer_faces(z['tetrahedra'][pair]));c=[0.,0,0];q=rounded_vertices[z['tetrahedra'][pair]];qv=np.einsum('ij,ij->i',q[:,1]-q[:,0],np.cross(q[:,2]-q[:,0],q[:,3]-q[:,0]))/6;assert np.all(qv>0);rounded_c=np.average(q.mean(axis=1),axis=0,weights=qv);assert cell.GetCentroid(c) and np.allclose(c,rounded_c,rtol=0,atol=1e-12)
# Recompute the full native quality measures from its serialized geometry fields.
face_centres=v[f].mean(axis=1);areas=np.cross(v[f[:,1]]-v[f[:,0]],v[f[:,2]]-v[f[:,0]])/2;mag=np.linalg.norm(areas[:ni],axis=1);tensor=np.zeros((nc,3,3));products=areas[:ni,:,None]*areas[:ni,None,:];np.add.at(tensor,o[:ni],products);np.add.at(tensor,n,products);counts=np.bincount(o[:ni],minlength=nc)+np.bincount(n,minlength=nc);sums=np.bincount(o[:ni],weights=mag,minlength=nc)+np.bincount(n,weights=mag,minlength=nc);average=np.divide(sums,counts,out=np.ones(nc),where=counts>0);det=np.abs(np.linalg.det(tensor/average[:,None,None]**2));delta=centres[n]-centres[o[:ni]];angles=np.degrees(np.arccos(np.clip(np.einsum('ij,ij->i',areas[:ni],delta)/(mag*np.linalg.norm(delta,axis=1)),-1,1)))
d1=np.abs(np.einsum('ij,ij->i',areas[:ni],face_centres[:ni]-centres[o[:ni]]));d2=np.abs(np.einsum('ij,ij->i',areas[:ni],centres[n]-face_centres[:ni]));weight=np.minimum(d1,d2)/(d1+d2);ratio=np.minimum(volumes[o[:ni]],volumes[n])/np.maximum(volumes[o[:ni]],volumes[n]);metrics={'nonorthogonal_faces_over_70':int((angles>70).sum()),'failed_determinants':int((det<.001).sum()),'interpolation_weight_below_005':int((weight<.05).sum()),'volume_ratio_below_001':int((ratio<.01).sum())};patterns={'nonorthogonal_faces_over_70':r'Number of severely non-orthogonal.*?faces: (\d+)','failed_determinants':r'Cells with small determinant.*?number of cells: (\d+)','interpolation_weight_below_005':r'Faces with small interpolation weight.*?number of faces: (\d+)','volume_ratio_below_001':r'Faces with small volume ratio.*?number of faces: (\d+)'};text=(case/'log.checkMesh.allGeometry').read_text()
for key,pattern in patterns.items():assert metrics[key]==int(re.search(pattern,text)[1]),(key,metrics[key])
result={'status':'complete_mixed_mesh_partition_geometry_VTK_and_native_field_audits_passed','source_sha256':sha(__file__),'helper_sha256':sha(aggl.__file__),'parent_audit_sha256':sha(parent/'assessment.json'),'agglomeration_receipt_sha256':sha(case/'agglomeration.json'),'native_check_sha256':sha(case/'native-check.json'),'vertices':len(v),'cells':nc,'tetrahedra':int((types==vtk.VTK_TETRA).sum()),'polyhedral_cells':int((types==vtk.VTK_POLYHEDRON).sum()),'boundary_triangles':len(f)-ni,'complete_parent_cell_partition_verified':True,'every_native_cell_independently_checked':True,'every_face_owner_neighbour_checked':True,'complete_boundary_and_marker_bijection_preserved':True,'exact_polyhedral_volume_equals_parent_sums':True,'points_file_byte_identical':True,'native_centroid_maximum_absolute_difference_m':float(np.abs(centres-expected_c).max()),'native_volume_maximum_relative_difference':float(np.max(np.abs(volumes-expected_v)/expected_v)),'independently_reproduced_native_quality':metrics,'extended_mesh_quality_passed':native['extended_mesh_quality_passed'],'VTK_point_precision_bits':8*vtk_points.dtype.itemsize,'VTK_points_equal_exact_forward_precision_conversion':True,'VTK_point_maximum_absolute_rounding_m':float(np.max(np.abs(rounded_vertices-v))),'native_double_points_exactly_preserved':True,'VTK_version':vtk.vtkVersion.GetVTKVersion(),'CFD_accepted':False,'manufacturing_authorized':False}
